using Maxx.Application.Common;
using Maxx.Domain.Common;
using Microsoft.AspNetCore.Diagnostics;
using Microsoft.AspNetCore.Mvc;

namespace Maxx.Api.Infrastructure;

/// <summary>Single place that turns exceptions into RFC 9457 problem details (ADR-003).</summary>
internal sealed class ProblemDetailsExceptionHandler(
    IProblemDetailsService problemDetails,
    ILogger<ProblemDetailsExceptionHandler> logger) : IExceptionHandler
{
    public async ValueTask<bool> TryHandleAsync(HttpContext httpContext, Exception exception, CancellationToken cancellationToken)
    {
        var (status, code, title, detail) = exception switch
        {
            RequestValidationException => (StatusCodes.Status400BadRequest, "request.invalid", "Requisição inválida", exception.Message),
            BadHttpRequestException => (StatusCodes.Status400BadRequest, "request.malformed", "Requisição inválida", "Não foi possível ler a requisição."),
            UnauthorizedException e => (StatusCodes.Status401Unauthorized, e.Code, "Não autenticado", e.Message),
            ForbiddenException e => (StatusCodes.Status403Forbidden, e.Code, "Sem permissão", e.Message),
            NotFoundException e => (StatusCodes.Status404NotFound, e.Code, "Não encontrado", e.Message),
            ConflictException e => (StatusCodes.Status409Conflict, e.Code, "Conflito", e.Message),
            DomainException e => (StatusCodes.Status422UnprocessableEntity, e.Code, "Regra não atendida", e.Message),
            OperationCanceledException => (499, "request.cancelled", "Requisição cancelada", "A requisição foi cancelada."),
            _ => (StatusCodes.Status500InternalServerError, "server.error", "Erro inesperado", "Algo deu errado do nosso lado. Tente novamente em instantes."),
        };

        if (status >= 500)
        {
            logger.LogError(exception, "Unhandled exception on {Method} {Path}", httpContext.Request.Method, httpContext.Request.Path);
        }

        httpContext.Response.StatusCode = status;
        var problem = new ProblemDetails
        {
            Status = status,
            Title = title,
            Detail = detail,
            Type = $"https://maxx.unimax.edu.br/errors/{code}",
        };
        problem.Extensions["code"] = code;
        if (exception is RequestValidationException validation)
        {
            problem.Extensions["errors"] = validation.Errors;
        }

        return await problemDetails.TryWriteAsync(new ProblemDetailsContext
        {
            HttpContext = httpContext,
            ProblemDetails = problem,
            Exception = exception,
        });
    }
}
EOF
