            doc.Info.Title = "Maxx API";
            doc.Info.Version = "v1";
            doc.Info.Description = "API da rede social gamificada da UniMax. Mudanças só aditivas em /v1.";
            return Task.CompletedTask;
        }));
        builder.Services.AddHealthChecks();
        return builder;
    }

    public static WebApplication UseMaxxApi(this WebApplication app)
    {
        app.UseExceptionHandler();
        app.UseStatusCodePages();
        app.MapOpenApi("/openapi/{documentName}.json");
        app.MapHealthEndpoints();
        return app;
    }
}
EOF
cat > Endpoints/HealthEndpoints.cs <<'EOF'
using Microsoft.AspNetCore.Diagnostics.HealthChecks;

namespace Maxx.Api.Endpoints;

internal static class HealthEndpoints
{
    public const string ReadyTag = "ready";

    public static void MapHealthEndpoints(this IEndpointRouteBuilder app)
    {
        app.MapHealthChecks("/health/live", new HealthCheckOptions { Predicate = _ => false })
            .ExcludeFromDescription();
        app.MapHealthChecks("/health/ready", new HealthCheckOptions { Predicate = c => c.Tags.Contains(ReadyTag) })
            .ExcludeFromDescription();
    }
}
